const seed=raw.map((r,i)=>({id:'b'+i,word:r[0],meaning:r[1],sentence:r[2],translation:r[3],category:r[4]}));
const base=[...seed,...QUESTION_BANK,...DICTIONARY];
const key='wordgarden-v1';let state;try{state=JSON.parse(localStorage.getItem(key))}catch{}state=Object.assign({progress:{},history:{},custom:[],goal:10,sound:true},state||{});let page='home',session=null,installEvent;const main=document.querySelector('#main');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const words=()=>[...base,...state.custom];const vocabulary=()=>{const m=new Map();for(const w of words()){const k=w.word.toLowerCase(),p=m.get(k);if(!p||(state.progress[w.id]?.star&&!state.progress[p.id]?.star)||((state.progress[w.id]?.attempts||0)>(state.progress[p.id]?.attempts||0)&&!state.progress[p.id]?.star))m.set(k,w)}return [...m.values()]};const due=()=>words().filter(w=>state.progress[w.id]&&state.progress[w.id].due<=Date.now());const today=()=>state.history[dayKey()]||{total:0,correct:0};function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('저장 공간을 확인해 주세요. 기록을 백업해 주세요.')}badge()}function badge(){document.querySelector('#reviewBadge').textContent=due().length||''}function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}function streak(){let n=0,d=new Date();if(!state.history[dayKey(d)]?.total)d.setDate(d.getDate()-1);while(state.history[dayKey(d)]?.total){n++;d.setDate(d.getDate()-1)}return n}function speak(text){if(!('speechSynthesis'in window)){toast('이 브라우저는 발음 재생을 지원하지 않아요.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;const v=speechSynthesis.getVoices().find(v=>v.lang==='en-US');if(v)u.voice=v;speechSynthesis.speak(u)}
const art=`<svg class="hero-art" viewBox="0 0 340 270" aria-hidden="true"><ellipse cx="176" cy="251" rx="137" ry="12" fill="#123e30"/><circle cx="215" cy="100" r="94" fill="#205b44"/><path d="M156 186 Q167 124 209 75" stroke="#aecf83" stroke-width="5" fill="none"/><path d="M185 118 C122 124 113 70 128 55 C175 53 197 87 185 118" fill="#b9d986"/><path d="M199 94 C205 40 247 25 273 38 C274 81 232 107 199 94" fill="#d7ec9d"/><path d="M167 155 C112 156 95 117 106 101 C150 91 176 124 167 155" fill="#88b566"/><path d="M177 136 C185 92 230 96 250 109 C234 145 204 156 177 136" fill="#a5cc79"/><path d="M120 176 L220 176 L205 239 Q169 257 136 239Z" fill="#eedbbe"/><ellipse cx="170" cy="176" rx="51" ry="12" fill="#f7ead5"/><ellipse cx="170" cy="175" rx="40" ry="6" fill="#9b8063"/><path d="M163 174 L173 148" stroke="#9cb872" stroke-width="5"/><rect x="44" y="184" width="62" height="53" rx="7" transform="rotate(-10 44 184)" fill="#d7ee92"/><path d="M61 205 l9 9 18 -23" fill="none" stroke="#48683f" stroke-width="4" stroke-linecap="round"/><path d="M263 162 l4 9 10 2 -8 6 1 10 -8 -6 -9 4 3 -10 -6 -7 10 -1Z" fill="#d7ee92"/><circle cx="85" cy="81" r="4" fill="#b1cf7c"/><path d="M268 220 h17 m-8 -8 v16" stroke="#8db36c" stroke-width="2"/></svg>`;
function title(eyebrow,h,p,extra=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${h}</h1><p class="muted">${p}</p></div>${extra}</div>`}function home(){const t=today(),d=new Date(),learned=new Set(words().filter(w=>state.progress[w.id]?.level>=2).map(w=>w.word.toLowerCase())).size;main.innerHTML=title('YOUR DAILY ENGLISH','오늘도, 한 뼘 더 자라요.','영어 단어 6,000개 이상 · 예문 10,060개로 매일 새롭게.',`<span class="date">${d.getMonth()+1}.${String(d.getDate()).padStart(2,'0')} ${['SUN','MON','TUE','WED','THU','FRI','SAT'][d.getDay()]}</span>`)+`<section class="hero"><div><div class="eyebrow">A LITTLE EVERY DAY</div><h2>외우는 단어에서<br>쓰는 영어로.</h2><p>문장 속에서 발견하고,<br>나만의 속도로 익혀 보세요.</p><button class="primary" id="start">오늘의 학습 시작 <span>↗</span></button></div>${art}</section><div class="metrics"><div class="metric"><div class="metric-icon">♨</div><div><small>연속 학습</small><strong>${streak()}<span>일째</span></strong></div></div><div class="metric"><div class="metric-icon">✳</div><div><small>오늘 학습한 문장</small><strong>${t.total}<span>문장</span></strong></div></div><div class="metric"><div class="metric-icon">⚑</div><div><small>익숙해진 단어</small><strong>${learned}<span>개</span></strong></div></div></div><div class="two-cols"><section class="card"><div class="section-head"><h2>매일 조금씩, 꾸준하게</h2><button class="text-btn" data-page="settings">목표 설정 ↗</button></div><div class="goal-top"><span>오늘의 학습 목표</span><strong>${Math.min(t.total,state.goal)} / ${state.goal} 문장</strong></div><div class="progress"><div style="width:${Math.min(100,t.total/state.goal*100)}%"></div></div><div class="week">${Array.from({length:7},(_,i)=>{const x=new Date();x.setDate(x.getDate()-((x.getDay()+6)%7)+i);return `<div class="day ${dayKey(x)===dayKey()?'today':''} ${state.history[dayKey(x)]?.total?'done':''}">${['월','화','수','목','금','토','일'][i]}<b>${state.history[dayKey(x)]?.total?'✓':x.getDate()}</b></div>`}).join('')}</div></section><section class="card review-card"><div class="section-head"><h2>기억이 오래 머물도록</h2><span class="pill">맞춤 복습</span></div><p>잊어버리기 전에 다시 만나요.<br>복습할 단어를 모아 두었어요.</p><div class="review-line"><div><strong>${due().length}</strong> <span>개의 단어가 기다려요</span></div><button class="round-btn" data-page="review" aria-label="복습하기">↗</button></div></section></div><section class="card lab-home-card"><div><div class="eyebrow">ENGLISH STUDY LIBRARY</div><h2>영어 연구실이 정원에 들어왔어요.</h2><p class="muted">토익 단어 2,060개 · 숙어 193개 · 구동사 357개<br>5형식, 헷갈리는 표현, 필수 문법까지 총 2,662개 자료를 찾아보세요.</p></div><button class="primary" data-page="lab">영어 연구실 열기 ↗</button></section><div class="actions"><button class="secondary" data-page="practice">말하기 · ChatGPT 연습 ↗</button><button class="text-btn" data-page="stats">학습 기록 보기</button></div><p class="note">✧ 완벽하지 않아도 괜찮아요. 오늘의 한 문장이 내일의 자신감이 될 거예요.</p>`;document.querySelector('#start').onclick=()=>start(false)}
function show(p){stopPractice();page=p;session=null;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));({home,words:wordPage,review:reviewPage,lab:labPage,practice:practicePage,stats,settings}[p]||home)();window.scrollTo(0,0);badge()}function reviewPage(){main.innerHTML=title('MAKE IT STICK','다시 만나면, 더 오래 기억해요.','틀린 단어는 바로, 맞힌 단어는 간격을 두고 복습해요.')+`<section class="card empty"><div class="big">${due().length?'🌱':'✳'}</div><h2>${due().length?`지금 복습할 단어 ${due().length}개`:'지금은 복습할 단어가 없어요'}</h2><p class="muted">${due().length?'기억을 한 번 더 단단하게 만들어 볼까요?':'새로운 문장으로 정원을 조금 더 키워 보세요.'}</p><div class="actions" style="justify-content:center"><button class="primary" id="reviewStart">${due().length?'복습 시작하기':'새 단어 학습하기'}</button></div></section>`;document.querySelector('#reviewStart').onclick=()=>start(due().length>0)}
function start(review){let pool=review?due():words().filter(w=>!state.progress[w.id]||state.progress[w.id].due<=Date.now());if(!pool.length)pool=words();if(review){pool.sort((a,b)=>state.progress[a.id].due-state.progress[b.id].due)}else{for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}pool.sort((a,b)=>(!!state.progress[a.id])-(!!state.progress[b.id]));const used=new Set();pool=pool.filter(w=>{const k=w.word.toLowerCase();if(used.has(k))return false;used.add(k);return true})}session={items:pool.slice(0,state.goal),index:0,correct:0,answered:false,review};quiz()}
function quiz(){const s=session;if(!s)return;if(s.index>=s.items.length){main.innerHTML=title('WELL DONE','오늘의 배움이 자랐어요.','작은 한 걸음, 잘 해내셨어요.')+`<section class="card empty"><div class="big">🌿</div><h2>${s.items.length}문장 학습 완료</h2><p>정답 ${s.correct}개 · 다시 익힐 단어 ${s.items.length-s.correct}개</p><p class="muted">틀린 단어는 복습 목록에서 다시 만날 수 있어요.</p><div class="actions" style="justify-content:center"><button class="primary" data-page="home">오늘의 정원으로</button><button class="secondary" data-page="review">오답 복습하기</button></div></section>`;return}const w=s.items[s.index];s.answered=false;const rex=new RegExp(w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');const parts=w.sentence.split(rex);const masked=parts.length>1?parts.map(esc).join('<span class="blank">'+ '＿'.repeat(Math.min(8,w.word.length))+'</span>'):'<span class="blank">'+ '＿'.repeat(Math.min(8,w.word.length))+'</span>';main.innerHTML=`<div class="quiz"><div class="quiz-top"><button class="text-btn" id="exitQuiz">✕ 학습 끝내기</button><div class="progress"><div style="width:${s.index/s.items.length*100}%"></div></div><span class="muted">${s.index+1} / ${s.items.length}</span></div><div class="eyebrow">${s.review?'REVIEW YOUR WORDS':'GROW YOUR ENGLISH'}</div><h1>${w.kind==='word'?'이 뜻에 맞는 영어 단어는?':'빈칸에 알맞은 영어는?'}</h1><p class="muted">${w.kind==='word'?'한국어 뜻과 첫 글자를 보고 단어를 떠올려 보세요.':'문장을 떠올리며 직접 입력해 보세요.'}</p><section class="card quiz-card"><span class="pill">${esc(w.category)}</span><div class="question">${w.kind==='word'?esc(w.word[0])+' ·'.repeat(w.word.length-1):masked}</div><p class="translation">${esc(w.translation||w.meaning)}</p><form id="answerForm"><label class="muted" for="answer">${esc(w.meaning)}</label><input id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="영어 단어 또는 표현 입력" aria-label="정답 입력"><div class="actions"><button type="button" class="text-btn" id="hint">첫 글자 힌트</button><button type="button" class="text-btn" id="unknown">잘 모르겠어요</button></div><button class="primary">정답 확인하기</button></form><div id="feedback" aria-live="polite"></div></section></div>`;document.querySelector('#exitQuiz').onclick=()=>show('home');document.querySelector('#hint').onclick=()=>toast(`힌트: ${w.word[0]}${' ·'.repeat(Math.min(12,w.word.length-1))}`);document.querySelector('#unknown').onclick=()=>answer('');document.querySelector('#answerForm').onsubmit=e=>{e.preventDefault();const value=document.querySelector('#answer').value;if(!value.trim()){toast('정답을 입력하거나 ‘잘 모르겠어요’를 눌러 주세요.');return}answer(value)};if(innerWidth>760)document.querySelector('#answer').focus()}
const normalize=s=>s.toLowerCase().trim().replace(/[.!?]+$/,'').replace(/\s+/g,' ');function answer(input){const s=session;if(!s||s.answered)return;s.answered=true;const w=s.items[s.index],ok=normalize(input)===normalize(w.word);const prev=state.progress[w.id]||{level:0,attempts:0,correct:0};const level=ok?Math.min(prev.level+1,7):0;state.progress[w.id]={...prev,level,attempts:prev.attempts+1,correct:prev.correct+(ok?1:0),due:ok?Date.now()+[1,1,3,7,14,30,60,90][level]*86400000:Date.now()};const t=today();state.history[dayKey()]={total:t.total+1,correct:t.correct+(ok?1:0)};s.correct+=ok?1:0;save();document.querySelector('#answerForm').hidden=true;document.querySelector('#feedback').innerHTML=`<div class="feedback ${ok?'':'wrong'}"><div>${ok?'✓ 잘했어요!':'다음에 다시 기억해 봐요.'}</div><strong>${esc(w.word)}</strong> <span>· ${esc(w.meaning)}</span><p>${esc(w.sentence||w.ipa||'뜻으로 익히는 단어 문제')}</p></div><div class="actions"><button class="listen" id="listen">◖ 발음 듣기</button><button class="text-btn" id="saveWord">${state.progress[w.id].star?'★ 저장됨':'☆ 단어 저장'}</button></div><button class="primary" id="next">${s.index+1===s.items.length?'학습 결과 보기':'다음 문장 →'}</button>`;document.querySelector('#listen').onclick=()=>speak(w.sentence||w.word);document.querySelector('#saveWord').onclick=e=>{state.progress[w.id].star=!state.progress[w.id].star;save();e.target.textContent=state.progress[w.id].star?'★ 저장됨':'☆ 단어 저장'};document.querySelector('#next').onclick=()=>{s.index++;quiz()};if(state.sound)speak(w.word)}
let wordFilter='all',wordLimit=40;function wordPage(){main.innerHTML=title('MY VOCABULARY','나의 단어장',`${vocabulary().length.toLocaleString()}개 단어·표현 · ${base.length.toLocaleString()}개 문제 · 예문 10,060개`)+`<div class="word-toolbar"><input id="search" placeholder="영어 단어 또는 뜻 검색" aria-label="단어 검색"><button class="primary" id="addWord">+ 단어 추가</button></div><div class="actions" style="margin:0 0 20px">${[['all','전체'],['saved','저장한 단어'],['custom','직접 추가'],['learning','학습 중']].map(([id,l])=>`<button class="${wordFilter===id?'primary':'secondary'}" data-filter="${id}" style="padding:9px 14px;font-size:12px">${l}</button>`).join('')}</div><div id="wordList" class="word-list"></div>`;document.querySelector('#search').oninput=()=>{wordLimit=40;renderWords()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{wordFilter=b.dataset.filter;wordPage()});document.querySelector('#addWord').onclick=()=>document.querySelector('#addDialog').showModal();renderWords()}function renderWords(){const q=document.querySelector('#search').value.toLowerCase();const rows=vocabulary().filter(w=>(w.word.toLowerCase().includes(q)||w.meaning.includes(q))&&(wordFilter==='all'||wordFilter==='saved'&&state.progress[w.id]?.star||wordFilter==='custom'&&w.id.startsWith('c')||wordFilter==='learning'&&state.progress[w.id]));document.querySelector('#wordList').innerHTML=rows.length?rows.slice(0,wordLimit).map(w=>`<div class="word-row"><button data-speak="${esc(w.id)}" aria-label="${esc(w.word)} 발음 듣기">◖</button><div class="word-body"><strong>${esc(w.word)}</strong><small>${esc(w.meaning)}</small><button class="example-btn" data-examples="${esc(w.id)}">예문 보기 ↗</button></div><span class="word-tag">${esc(w.category)}</span><button data-star="${esc(w.id)}" aria-label="단어 저장" aria-pressed="${!!state.progress[w.id]?.star}">${state.progress[w.id]?.star?'★':'☆'}</button>${w.id.startsWith('c')?`<button data-delete="${esc(w.id)}" aria-label="단어 삭제">×</button>`:''}</div>`).join(''):'<section class="card empty"><p>아직 단어가 없어요.</p><p class="muted">단어를 검색하거나 새로 추가해 보세요.</p></section>';if(rows.length>wordLimit){const more=document.createElement('button');more.className='secondary';more.textContent=`더 보기 (${Math.min(wordLimit,rows.length)} / ${rows.length})`;more.onclick=()=>{wordLimit+=40;renderWords()};document.querySelector('#wordList').append(more)}document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(words().find(w=>w.id===b.dataset.speak).word));document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{let p=state.progress[b.dataset.star];if(!p)p=state.progress[b.dataset.star]={level:0,attempts:0,correct:0,due:Date.now()};p.star=!p.star;save();renderWords()});document.querySelectorAll('[data-examples]').forEach(b=>b.onclick=()=>showExamples(b.dataset.examples));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('직접 추가한 이 단어를 삭제할까요?')){state.custom=state.custom.filter(w=>w.id!==b.dataset.delete);delete state.progress[b.dataset.delete];save();renderWords()}})}
function stats(){const entries=Object.entries(state.history).sort((a,b)=>b[0].localeCompare(a[0]));const total=entries.reduce((n,[,v])=>n+v.total,0),correct=entries.reduce((n,[,v])=>n+v.correct,0);main.innerHTML=title('YOUR GROWTH','차곡차곡 쌓인 나의 기록','어제보다 조금 더 익숙해진 영어를 만나세요.')+`<div class="stats-grid">${[['총 학습 문장',total+''],['전체 정답률',total?Math.round(correct/total*100)+'%':'—'],['학습한 날짜',entries.length+'일'],['연속 학습',streak()+'일']].map(([l,v])=>`<section class="card"><p class="muted">${l}</p><div class="stat-num">${v}</div></section>`).join('')}</div><section class="card" style="margin-top:20px"><h2>날짜별 학습</h2>${entries.length?entries.slice(0,60).map(([d,v])=>`<div class="history-row"><span>${d}</span><span>${v.total}문장 · 정답 ${v.correct}개</span></div>`).join(''):'<p class="muted">첫 학습을 시작하면 이곳에 기록이 쌓여요.</p>'}</section>`}
function settings(){main.innerHTML=title('MAKE IT YOURS','나에게 맞는 학습 습관','학습 목표와 소중한 기록을 관리하세요.')+`<div class="settings"><section class="card"><h2>학습 설정</h2><label>하루 학습 목표<select id="goal">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n}문장</option>`).join('')}</select></label><label>정답 확인 후 자동 발음<input id="sound" type="checkbox" ${state.sound?'checked':''}></label></section><section class="card"><h2>휴대폰에 앱처럼 설치하기</h2><p class="muted">이 사이트 주소를 휴대폰 Safari에서 여세요. 단어정원은 로그인 없이 사용할 수 있어요.</p><ol class="install-steps"><li><strong>iPhone · Safari</strong>에서 공유 버튼 → ‘홈 화면에 추가’</li><li><strong>Android · Chrome</strong>에서 메뉴 ⋮ → ‘홈 화면에 추가’ 또는 ‘앱 설치’</li></ol><p class="muted">설치 메뉴는 브라우저와 기기에 따라 달라요. 네이티브 앱이 아닌 설치형 웹앱입니다.</p><button class="secondary" id="install">설치 안내 / 설치하기 ↗</button></section><section class="card"><h2>오프라인 학습</h2><p class="muted" id="offlineStatus" role="status">저장 상태를 확인해 보세요.</p><button class="secondary" id="offlineCheck">오프라인 저장 확인</button><p class="muted">자료를 처음 저장하거나 업데이트할 때는 인터넷이 필요해요. ChatGPT 대화에는 인터넷과 ChatGPT 로그인이 필요합니다. iPhone이 사이트 데이터를 지우면 다시 연결해 자료를 받아야 해요.</p></section><section class="card"><h2>내 기록 백업</h2><p class="muted">기록은 이 기기의 브라우저에 저장됩니다. 다른 기기와 자동 동기화되지 않으며, 브라우저 데이터를 지우면 사라질 수 있어요.</p><div class="actions"><button class="secondary" id="export">백업 파일 내보내기 ↓</button><button class="secondary" id="import">백업 파일 가져오기 ↑</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></section><section class="card"><h2>단어정원 소개</h2><p class="muted">영한 사전의 서로 다른 영어 표제어 6,000개, 기본 예문 60개와 패턴 조합 예문 10,000개를 제공합니다. 총 16,060문제이며, 모든 단어에 예문이 있는 것은 아닙니다. <a href="data-credits.html" target="_blank" rel="noopener" style="text-decoration:underline">데이터 출처와 라이선스 ↗</a> 정답은 1·3·7·14·30·60·90일 간격으로, 오답은 바로 복습합니다. 영어 연구실에는 토익 어휘·숙어·구동사와 문법 자료 2,662개가 별도로 수록되어 있습니다. 연구실 자료는 원문의 뜻, 발음기호, 예문, 비교 설명을 모두 보존하며 기존 퀴즈의 개수에는 포함하지 않습니다. 특정 서비스와 제휴하지 않은 개인용 영어 학습 도구입니다.</p><button class="text-btn danger" id="reset">모든 학습 기록 초기화</button></section></div>`;document.querySelector('#offlineCheck').onclick=showOfflineStatus;showOfflineStatus();document.querySelector('#goal').onchange=e=>{state.goal=Number(e.target.value);save();toast('학습 목표를 저장했어요.')};document.querySelector('#sound').onchange=e=>{state.sound=e.target.checked;save()};document.querySelector('#install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null}else toast('Safari의 공유 또는 Chrome의 메뉴에서 홈 화면에 추가하세요.')};document.querySelector('#export').onclick=()=>{const b=new Blob([JSON.stringify({format:'wordgarden',version:1,data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`wordgarden-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('#import').onclick=()=>document.querySelector('#importFile').click();document.querySelector('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const b=JSON.parse(await f.text()),d=b.data;if(b.format!=='wordgarden'||b.version!==1||!d||!Array.isArray(d.custom)||!d.progress||!d.history||![5,10,15,20].includes(d.goal)||typeof d.sound!=='boolean')throw Error();for(const w of d.custom)if(typeof w.id!=='string'||!w.id.startsWith('c')||!['word','meaning','sentence','translation','category'].every(k=>typeof w[k]==='string')||!w.word.trim()||w.word.length>60)throw Error();for(const p of Object.values(d.progress))if(!p||!Number.isInteger(p.level)||p.level<0||p.level>7||![p.due,p.attempts,p.correct].every(Number.isFinite)||p.correct>p.attempts||p.correct<0)throw Error();for(const [k,v]of Object.entries(d.history))if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!v||![v.total,v.correct].every(Number.isInteger)||v.total<0||v.correct<0||v.correct>v.total)throw Error();if(confirm('현재 기록을 백업 파일의 기록으로 바꿀까요?')){state=d;save();settings();toast('백업을 가져왔어요.')}}catch{toast('올바른 단어정원 백업 파일을 선택해 주세요.')}};document.querySelector('#reset').onclick=()=>{if(confirm('학습 기록과 직접 추가한 단어를 모두 삭제할까요? 먼저 백업을 권장해요.')){state={progress:{},history:{},custom:[],goal:10,sound:true};save();show('home')}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();show(b.dataset.page)}});document.querySelector('.brand').onclick=e=>{e.preventDefault();show('home')};document.querySelector('#closeAdd').onclick=()=>document.querySelector('#addDialog').close();document.querySelector('#addForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),word=f.get('word').trim(),meaning=f.get('meaning').trim();if(!word||!meaning)return;const sentence=f.get('sentence').trim()||word;if(!sentence.toLowerCase().includes(word.toLowerCase())){toast('예문에 입력한 영어 단어를 포함해 주세요.');return}state.custom.push({id:'c'+crypto.randomUUID(),word,meaning,sentence,translation:meaning,category:'내 단어'});save();e.target.reset();document.querySelector('#addDialog').close();wordFilter='custom';show('words');toast('나의 단어장에 추가했어요.')};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});show('home');

function showExamples(id){const w=words().find(w=>w.id===id);if(!w)return;const list=words().filter(x=>x.word.toLowerCase()===w.word.toLowerCase()&&x.sentence);main.innerHTML=title('WORD IN CONTEXT',esc(w.word),`${esc(w.meaning)} · 예문 ${list.length}개`)+`<button class="secondary" data-page="words">← 단어장으로</button><div class="word-list" style="margin-top:20px">${list.length?'':'<section class="card"><p>이 단어는 뜻 맞히기와 발음 듣기로 학습할 수 있어요.</p><p class="muted">연결된 문장 예문은 아직 없습니다.</p></section>'}${list.map(x=>`<section class="card"><p style="font:20px/1.6 Outfit,sans-serif">${esc(x.sentence)}</p><p class="muted">${esc(x.translation)}</p><button class="listen" data-example-speak="${esc(x.id)}">◖ 문장 듣기</button></section>`).join('')}</div>`;document.querySelectorAll('[data-example-speak]').forEach(b=>b.onclick=()=>speak(words().find(x=>x.id===b.dataset.exampleSpeak).sentence));window.scrollTo(0,0)}
